from shiny import App, ui, render, reactive, Inputs, Outputs, Session

app_ui = ui.page_fluid(
    ui.layout_columns(
        # First column: controlling inputs
        ui.card(
            ui.h4("Controls"),
            ui.input_slider("num", "Number (1-10)", min=1, max=10, value=5),
            ui.input_select("color", "Color", choices=["Red", "Green", "Blue"], selected="Red"),
        ),
        # Second column: controlled inputs
        ui.card(
            ui.h4("Controlled Inputs"),
            ui.input_slider("controlled_slider", "Controlled Slider", min=1, max=10, value=5),
            ui.input_select("controlled_select", "Controlled Select", choices=["A", "B", "C"], selected="A"),
        ),
        # Third column: more inputs and a tabset
        ui.card(
            ui.h4("Other Inputs & Tabs"),
            ui.input_text("text_input", "Text Input", value="Hello"),
            ui.input_checkbox("checkbox_input", "Checkbox", value=False),
            ui.navset_tab(
                ui.nav("Tab 1", ui.output_text_verbatim("tab1_out")),
                ui.nav("Tab 2", ui.output_text_verbatim("tab2_out")),
            ),
        ),
        widths=[4, 4, 4]
    )
)

def server(input: Inputs, output: Outputs, session: Session):
    @reactive.effect
    def _():
        # Update controlled_slider based on num
        session.send_input_message("controlled_slider", {"value": input.num()})
        # Update controlled_select choices based on color
        color_map = {
            "Red": ["A", "B"],
            "Green": ["B", "C"],
            "Blue": ["A", "C"]
        }
        session.send_input_message(
            "controlled_select",
            {
                "choices": color_map[input.color()],
                "selected": color_map[input.color()][0]
            }
        )
        # Update text_input and checkbox_input in third column
        session.send_input_message("text_input", {"value": f"Selected: {input.color()}"})
        session.send_input_message("checkbox_input", {"value": input.num() % 2 == 0})

    @output
    @render.text
    def tab1_out():
        return f"Slider: {input.controlled_slider()}, Select: {input.controlled_select()}"

    @output
    @render.text
    def tab2_out():
        return f"Text: {input.text_input()}, Checkbox: {input.checkbox_input()}"

app = App(app_ui, server, debug=True)
